def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def multiply(a, b):
    return a * b

def divide(a, b):
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

def main():
    print("Simple Calculator")
    print("Operations: +, -, *, /")

    while True:
        try:
            expr = input("\nEnter calculation (or 'quit' to exit): ").strip()
            if expr.lower() == 'quit':
                break

            parts = expr.split()
            if len(parts) != 3:
                print("Format: <num> <op> <num> (e.g., 2 + 3)")
                continue

            a = float(parts[0])
            op = parts[1]
            b = float(parts[2])

            if op == '+':
                result = add(a, b)
            elif op == '-':
                result = subtract(a, b)
            elif op == '*':
                result = multiply(a, b)
            elif op == '/':
                result = divide(a, b)
            else:
                print("Invalid operator. Use +, -, *, /")
                continue

            print(f"Result: {result}")

        except ValueError as e:
            print(f"Error: {e}")
        except KeyboardInterrupt:
            break

if __name__ == "__main__":
    main()

